    "Wala nang kanin.": ["Wala nang kanin, kaya magluluto ulit ako.","There's no more rice, so I'll cook some more."],
    "palengke": ["Maaga kaming pumupunta sa palengke para sariwa ang isda.","We go to the market early so the fish is fresh."],
    "Binili ko ang isda.": ["Binili ko ang isda sa palengke kaninang umaga.","I bought the fish at the market this morning."],
    "bahay ni Lola": ["Tuwing Pasko, nagkikita kami sa bahay ni Lola.","Every Christmas, we get together at Lola's house."],
    "Alas-sais ako gumising.": ["Alas-sais ako gumising kasi may pasok ako.","I woke up at six because I had work."],
    "Pupunta ako kina Lola.": ["Pupunta ako kina Lola sa Linggo.","I'm going to Lola's place on Sunday."],
    "Nasa tabi ng simbahan.": ["Nasa tabi ng simbahan ang botika.","The pharmacy is next to the church."],
    "doon": ["Doon ang sakayan ng jeep.","The jeepney stop is over there."],
    "Pakiabot po ang bayad.": ["Pakiabot po ang bayad ko, salamat po.","Please pass my fare forward, thank you."],
    "tricycle": ["Sumakay kami ng tricycle papunta sa palengke.","We took a tricycle to the market."],
    "Sasakay ako ng jeep.": ["Sasakay ako ng jeep papuntang opisina.","I'll take a jeepney to the office."],
    "Uminom ka ng gamot.": ["Uminom ka ng gamot at magpahinga ka.","Take some medicine and get some rest."],
    "Kailangan ko ng doktor.": ["Kailangan ko ng doktor ngayon.","I need a doctor now."],
    "Huwag kang mag-alala.": ["Huwag kang mag-alala, malapit lang ang ospital.","Don't worry, the hospital is close."],
    "Walang pasok ngayon.": ["Walang pasok ngayon dahil sa bagyo.","There's no school or work today because of the typhoon."],
    "Magtatrabaho ako bukas.": ["Magtatrabaho ako bukas, pero libre ako sa Linggo.","I'll work tomorrow, but I'm free on Sunday."],
    "Tapos na ang klase.": ["Tapos na ang klase, uuwi na ako.","Class is over; I'm going home now."],
