      {"t":"fill","q":"bahay __ Ana","p":"Ana's house","a":["ni"],"o":["si","ng","kay"],"why":"ni marks the owner when the owner is a name."},
      {"t":"fill","q":"Kuya, __ Makati po.","p":"To Makati, please.","a":["sa"],"o":["kay","si","ang"],"why":"The sa marker shows the place."},
      {"t":"type","p":"Ana is a teacher","a":["Guro si Ana","Si Ana ay guro"],"hint":"guro (teacher) · Ana","x":["ang"],"why":"si goes before a name that is the topic: Guro si Ana."},
      {"t":"type","p":"the teacher's house","a":["bahay ng guro","ang bahay ng guro"],"hint":"bahay (house) · guro (teacher)","x":["ni"],"why":"The ng marker shows the owner when it is an ordinary noun: bahay ng guro."},
      {"t":"type","p":"This is for Juan","a":["Para kay Juan ito","Ito ay para kay Juan"],"hint":"para (for) · Juan · ito","x":["sa"],"why":"kay is for people, sa for places: para kay Juan."}
