      {"t":"order","p":"I have a dog (use mayroon)","a":["Mayroon","akong","aso"],"x":["ako"],"why":"mayroon is linked to the pronoun with -ng: Mayroon akong aso."},
      {"t":"order","p":"She doesn't have a dog","a":["Wala","siyang","aso"],"x":["siya"],"why":"wala is linked to the pronoun: siya becomes siyang."},
      {"t":"order","p":"Ana has a dog","a":["May","aso","si","Ana"],"x":["ang"],"why":"si goes before a person's name: May aso si Ana."},
      {"t":"fill","q":"__ kanin ba?","p":"Is there any rice?","a":["May"],"o":["Wala","Ang","Hindi"],"why":"may goes straight before the noun to ask if there is any."},
      {"t":"fill","q":"Mayroon __ pera.","p":"We have money. (we, not you)","a":["kaming"],"o":["kami","namin","tayong"],"why":"kami (we, not you) takes -ng after mayroon: kaming."},
      {"t":"fill","q":"May adobo ba? — __ po.","p":"Is there any adobo? — Yes, there is. (polite)","a":["Mayroon","Meron"],"o":["May","Hindi","Huwag"],"why":"Mayroon alone answers \"Yes, there is\"; may always needs a noun after it."},
      {"t":"type","p":"I have a brother or sister (use mayroon)","a":["Mayroon akong kapatid","Meron akong kapatid"],"hint":"mayroon · ako · kapatid","x":["ako"],"why":"mayroon is linked to the pronoun with -ng: Mayroon akong kapatid."},
      {"t":"type","p":"There's no coffee.","a":["Walang kape"],"hint":"wala · kape","x":["wala"],"why":"wala is linked to the noun with -ng: Walang kape."},
      {"t":"type","p":"Is there any water? (polite)","a":["May tubig po ba","Mayroon po bang tubig","Meron po bang tubig"],"hint":"may · tubig · po comes before ba","x":["ang"],"why":"po comes before ba: May tubig po ba?"}
